  function close(){if(closed)return;closed=true;clearInterval(guardTimer);stop();if(dialog.open)dialog.close();dialog.remove();if(active?.dialog===dialog)active=null;if(opener?.isConnected&&!opener.closest('[hidden],details:not([open])')&&(!opener.closest('dialog')||opener.closest('dialog').open))opener.focus();else document.querySelector('[aria-label="Chat menu"],#account-toggle')?.focus();}
  function controls(){const focused=document.activeElement;newer.disabled=busy||index===0;older.disabled=busy||(!hasMore&&index>=items.length-1);if(focused===newer&&newer.disabled||focused===older&&older.disabled)dialog.querySelector('[data-gallery-close]').focus();count.textContent=items.length?(index+1)+' / '+items.length+(hasMore?' loaded':''):'No media';}
  function render(){if(!valid()){close();return;}const hadFocus=dialog.contains(document.activeElement);stop();strip.replaceChildren();const file=items[index];if(!file){caption.textContent='';controls();return;}if(file.mime.startsWith('image/')){const image=document.createElement('img');image.src=file.url;image.alt='Shared photo';image.draggable=false;stage.append(image);}else{stage.innerHTML=mediaMessage(file);installVoiceNoteStyle();bindVoiceNotes(stage);}const when=new Date(Number(file.at));caption.textContent=(file.from==='admin'?'Goddess':'Sub')+' · '+(Number.isNaN(when.getTime())?'':when.toLocaleString());
   for(let i=Math.max(0,index-5);i<Math.min(items.length,index+6);i++){const f=items[i],button=document.createElement('button');button.type='button';button.className='quiet';const kind=f.mime.startsWith('image/')?'Photo':f.mime.startsWith('video/')?'Video':f.mime.startsWith('audio/')?'Voice note':'File';button.textContent=kind+' '+(i+1);button.setAttribute('aria-label','View '+kind.toLowerCase()+' '+(i+1));button.setAttribute('aria-pressed',String(i===index));button.onclick=()=>{index=i;status.textContent='';render();};strip.append(button);}controls();if(hadFocus&&!dialog.contains(document.activeElement))dialog.querySelector('[data-gallery-close]').focus();}
  async function history(){if(busy||!hasMore||!valid())return false;busy=true;retry.hidden=true;status.textContent='Loading shared media…';controls();try{const page=await load(before);if(!valid()){close();return false;}if(!Array.isArray(page.files)||page.files.length>600)throw Error('Media history unavailable.');const safe=page.files.filter(file=>typeof file.id==='string'&&/^\/api\/media\/[a-f0-9-]{36}$/.test(file.url||'')&&typeof file.mime==='string');const seen=new Set(items.map(file=>file.id));for(const file of safe)if(!seen.has(file.id)){items.push(file);seen.add(file.id);}const cursor=page.nextBefore??page.files.at(-1)?.seq;if(page.hasMore&&(!Number.isSafeInteger(cursor)||cursor<1||before!==null&&cursor>=before))throw Error('Media history could not continue.');before=cursor;hasMore=page.hasMore===true;status.textContent=items.length?'Newest first · Swipe or use the arrow keys.':'No shared media yet.';render();return true;}catch(error){if(valid()){status.textContent=error.message||'Could not load shared media.';retry.hidden=false;}return false;}finally{busy=false;if(valid())controls();}}
  async function move(step){if(!valid()){close();return;}if(busy)return;let next=index+step;if(next<0)return;if(next>=items.length&&hasMore){if(!await history())return;}if(next<items.length){index=next;status.textContent='';render();}}
  newer.onclick=()=>move(-1);older.onclick=()=>move(1);retry.onclick=()=>history();dialog.querySelector('[data-gallery-close]').onclick=close;dialog.addEventListener('cancel',event=>{event.preventDefault();close();});dialog.addEventListener('close',close);dialog.addEventListener('keydown',event=>{if(event.altKey||event.ctrlKey||event.metaKey||event.target.closest('input,textarea,select,audio,video,[contenteditable="true"]'))return;if(event.key==='ArrowLeft'||event.key==='ArrowRight'){event.preventDefault();move(event.key==='ArrowLeft'?-1:1);}});
